#include <vector>
std::vector<int> v;
v.push_back(10);
v.size(); v.pop_back(); v.clear();

example:
#include <iostream>
#include <vector>
int main() {
    std::vector<int> v;
    v.push_back(5); v.push_back(15);
    for (size_t i = 0; i < v.size(); ++i) std::cout << v[i] << ' ';
}

syntax:
#include <map>
#include <set>
std::set<int> s; s.insert(5); s.count(5);
std::map<std::string, int> mp; mp["UHL"] = 1;

example:
#include <iostream>
#include <map>
int main() {
    std::map<char, int> cnt;
    cnt['a']++; cnt['b'] += 2;
    std::cout << cnt['a'] << ' ' << cnt['b'] << '\n'; // 1 2
}

#include <iostream>
#include <stack>
int main() {
    std::stack<int> st;
    st.push(10); st.push(20);
    std::cout << st.top() << '\n'; // 20
    st.pop();
}

syntax:
for (std::vector<int>::iterator it = v.begin(); it != v.end(); ++it) {
    std::cout << *it << ' ';
}

example:
#include <iostream>
#include <set>
int main() {
    std::set<int> s; s.insert(30); s.insert(10);
    for (std::set<int>::iterator it = s.begin(); it != s.end(); ++it)
        std::cout << *it << ' '; // 10 30
}

syntax:
#include <algorithm>
std::sort(arr, arr + n);
std::sort(v.begin(), v.end());
bool ok = std::binary_search(v.begin(), v.end(), target);

example:
#include <iostream>
#include <algorithm>
int main() {
    int a[5] = {5, 1, 4, 2, 3};
    std::sort(a, a + 5);
    for (int i = 0; i < 5; ++i) std::cout << a[i] << ' '; // 1 2 3 4 5
}
